/* @lc app=leetcode id=1765 lang=kotlin */ class Solution { fun highestPeak(isWater: Array<IntArray>): Array<IntArray> = Array(isWater.size) { IntArray(isWater[0].size) { -1 } }.also { h -> generateSequence(isWater.indices.flatMap { i -> isWater[0].indices.filter { isWater[i][it] == 1 }.map { i to it } }.onEach { (i, j) -> h[i][j] = 0 } to 0) { (f, lv) -> f.flatMap { (i, j) -> listOf(i + 1 to j, i - 1 to j, i to j + 1, i to j - 1) }.filter { (i, j) -> i in h.indices && j in h[0].indices && h[i][j] == -1 }.distinct().onEach { (i, j) -> h[i][j] = lv + 1 }.takeIf { it.isNotEmpty() }?.let { it to lv + 1 } }.count() } }